export interface HooksModel {
  /** Python functions and classes this server calls at set points. They are loaded when the agent server starts, so a change takes effect only after a restart. A path that cannot be loaded is logged, and the agent server then refuses to run agents until it is fixed. Every function must be async and takes one dict argument holding what is relevant to the call, including isValidation. Only vault, encryptionKey and restore return a value. To refuse, a function raises an exception, and its message is shown as it is. The code must be installed on every agent server of this account. */
  type?: 'hooks';
  /** Called once when the agent server starts. If it raises, the server does not start. */
  onStart?: string | null;
  /** Called when the agent server shuts down normally. It is not called if the process is killed. If it raises, the message is logged. */
  onEnd?: string | null;
  /** Called before an agent runs, with isNewConversation and startFromAsk. If it raises, the agent stops. */
  onAgentStart?: string | null;
  /** Called after an agent finishes successfully or pauses to ask, with endWithAsk, before the run is recorded. If it raises, the agent fails. */
  onAgentEnd?: string | null;
  /** Called after an agent fails, before the run is recorded. If it raises, its message is reported as the error. */
  onAgentError?: string | null;
  /** Called after an agent is published, with its name, version, definition, title, tag and the publisher's email. If it raises, the caller gets an error that says the agent was published. */
  onAgentPublish?: string | null;
  /** Called after an agent is deleted, with its name. If it raises, the caller gets an error that says the agent was deleted. */
  onAgentDelete?: string | null;
  /** Stores a conversation's state, given convid, state, userEmail and agentName. The state is not encrypted by this server, and ownership is not checked by Search2o Cloud. Validation runs keep their state in Search2o Cloud. Set together with restore and deleteConversation. */
  save?: string | null;
  /** Returns the state stored by save for a convid, or None when there is none. It also receives userEmail, so it can check who owns the conversation. Set together with save and deleteConversation. */
  restore?: string | null;
  /** Deletes the state stored by save for a convid. Set together with save and restore. Expiring stored state is the customer's responsibility. */
  deleteConversation?: string | null;
  /** Returns the value of a secret, given its name, for the vault secret source. Called before an agent runs, for each secret the agent reads. */
  vault?: string | null;
  /** Returns the encryption key as bytes, given keyName, for end-to-end encryption. */
  encryptionKey?: string | null;
  /** Called with each request before it is sent to a language model. It cannot change the request. If it raises, the agent stops. */
  beforeLlmCall?: string | null;
  /** Called with each response from a language model. It cannot change the response. If it raises, the agent stops. */
  afterLlmCall?: string | null;
  /** Called before an api command sends its request, with the method, URL, headers, query parameters, body and profile. If it raises, the request is not sent and the agent stops. */
  beforeApiCall?: string | null;
  /**
     * LlmAdapter classes that add support for more language model vendors. Each must build with no arguments.
     * @items.maxLength 200
     * @items.pattern ^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)+$
     */
  llmAdapters?: string[];
  /** A function per agent configuration part that checks a profile before it is saved, given the profile. If it raises, the save is refused with its message. */
  agentConfigValidators?: Partial<Record<AgentConfigPart, string>>;
}

